# Step 1: Calculate the global average review rating across all reviews.
global_average_reviews_rating = GRAPH.CALCULATE(
    avg_val=AVG(review.rating)
)

# Step 2: Filter items. For each item, check if it has any review
# with a rating higher than the global average.
# Use .SINGULAR() to access the calculated global average value.
result = items.WHERE(
    HAS(
        reviews.WHERE(
            rating > global_average_reviews_rating.SINGULAR().avg_val
        )
    ) == 1
).CALCULATE(
    item_title=title
)

